// @domain: domains
//! The store trait every generated API reads and writes through (#4478). Settings pick
//! the backend; the door rules sit above it, so no backend can skip them.
//! Generated by athena-gen from its template — DO NOT EDIT; change the generator.

use crate::model::{ClassDef, NS};
use crate::settings::Settings;
use serde_json::{json, Map, Value};

/// One row as the API serves it: name, label, status, then every field the shape declares.
pub type Row = Map<String, Value>;

pub trait RowStore: Send + Sync {
    /// A page of rows, ordered by name, and the total count.
    fn list(&self, class: &ClassDef, limit: usize, offset: usize) -> Result<(Vec<Row>, usize), String>;
    /// One row by name, or None.
    fn get(&self, class: &ClassDef, name: &str) -> Result<Option<Row>, String>;
}

/// A row's IRI from its name: `<kind>-<name>`, where kind is the class in kebab case
/// (StreamEvent → stream-event). The name read back is the name written (v1 requirement 6).
pub fn iri(class: &ClassDef, name: &str) -> String {
    format!("{NS}{}-{name}", class.kind)
}

pub fn name_of(class: &ClassDef, iri: &str) -> String {
    let local = iri.rsplit(['#', '/']).next().unwrap_or(iri);
    local.strip_prefix(&format!("{}-", class.kind)).unwrap_or(local).to_string()
}

pub fn open(s: &Settings) -> Box<dyn RowStore> {
    match s.store_kind.as_str() {
        "sparql" => Box::new(Sparql { endpoint: s.store_endpoint.clone(), auth: s.store_auth() }),
        other => {
            eprintln!("{}: store kind '{other}' is not built yet (sparql is); refusing to start", crate::model::PRODUCT);
            std::process::exit(2);
        }
    }
}

/// Remote SPARQL 1.1 (Fuseki here). Reads only in this step.
pub struct Sparql {
    endpoint: String,
    auth: Option<(String, String)>,
}

fn b64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in bytes.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
        let n = (u32::from(b[0]) << 16) | (u32::from(b[1]) << 8) | u32::from(b[2]);
        for i in 0..4 {
            if i <= chunk.len() {
                out.push(char::from(T[((n >> (18 - 6 * i)) & 63) as usize]));
            } else {
                out.push('=');
            }
        }
    }
    out
}

fn local(v: &str) -> String {
    v.rsplit(['#', '/']).next().unwrap_or(v).to_string()
}

/// One SELECT against a remote SPARQL endpoint, as the raw SPARQL-JSON body.
pub fn sparql_body(endpoint: &str, auth: &Option<(String, String)>, query: &str) -> Result<String, String> {
    let mut req = ureq::post(&format!("{}/query", endpoint.trim_end_matches('/')))
        .set("Accept", "application/sparql-results+json");
    if let Some((u, p)) = auth {
        req = req.set("Authorization", &format!("Basic {}", b64(format!("{u}:{p}").as_bytes())));
    }
    let resp = req.send_form(&[("query", query)]).map_err(|e| format!("store: {e}"))?;
    resp.into_string().map_err(|e| format!("store: {e}"))
}

impl Sparql {
    fn select(&self, query: &str) -> Result<Vec<Map<String, Value>>, String> {
        let text = sparql_body(&self.endpoint, &self.auth, query)?;
        let body: Value = serde_json::from_str(&text).map_err(|e| format!("store: {e}"))?;
        let rows = body["results"]["bindings"].as_array().cloned().unwrap_or_default();
        Ok(rows.into_iter().filter_map(|r| r.as_object().cloned()).collect())
    }

    fn rows(&self, class: &ClassDef, subjects: &[String]) -> Result<Vec<Row>, String> {
        if subjects.is_empty() {
            return Ok(Vec::new());
        }
        let values: String = subjects.iter().map(|s| format!("<{s}> ")).collect();
        let q = format!(
            "SELECT ?s ?p ?o WHERE {{ VALUES ?s {{ {values}}} GRAPH <{g}> {{ ?s ?p ?o }} }}",
            g = class.graph
        );
        let triples = self.select(&q)?;
        let mut out = Vec::new();
        for s in subjects {
            let mut row = Row::new();
            row.insert("name".into(), json!(name_of(class, s)));
            let vals = |pred: &str| -> Vec<String> {
                triples.iter()
                    .filter(|t| t["s"]["value"] == json!(s) && t["p"]["value"] == json!(pred))
                    .map(|t| {
                        let v = t["o"]["value"].as_str().unwrap_or("").to_string();
                        if t["o"]["type"] == json!("uri") { local(&v) } else { v }
                    })
                    .collect()
            };
            row.insert("label".into(), json!(vals(&format!("{NS}label")).into_iter().next().unwrap_or_default()));
            row.insert("status".into(), json!(vals(&format!("{NS}status")).into_iter().next().unwrap_or_default()));
            for f in class.fields {
                let mut v = vals(&format!("{NS}{}", f.name));
                v.sort();
                let value = if f.many { json!(v) } else { json!(v.into_iter().next().unwrap_or_default()) };
                row.insert(f.name.into(), value);
            }
            out.push(row);
        }
        Ok(out)
    }
}

impl RowStore for Sparql {
    fn list(&self, class: &ClassDef, limit: usize, offset: usize) -> Result<(Vec<Row>, usize), String> {
        let count = self.select(&format!(
            "SELECT (COUNT(DISTINCT ?s) AS ?n) WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} }}",
            g = class.graph, c = class.name
        ))?;
        let total = count.first().and_then(|r| r["n"]["value"].as_str()).and_then(|n| n.parse().ok()).unwrap_or(0);
        let page = self.select(&format!(
            "SELECT DISTINCT ?s WHERE {{ GRAPH <{g}> {{ ?s a <{NS}{c}> }} }} ORDER BY ?s LIMIT {limit} OFFSET {offset}",
            g = class.graph, c = class.name
        ))?;
        let subjects: Vec<String> = page.iter().filter_map(|r| r["s"]["value"].as_str().map(String::from)).collect();
        Ok((self.rows(class, &subjects)?, total))
    }

    fn get(&self, class: &ClassDef, name: &str) -> Result<Option<Row>, String> {
        let s = iri(class, name);
        let hit = self.select(&format!(
            "SELECT ?s WHERE {{ GRAPH <{g}> {{ <{s}> a <{NS}{c}> . BIND(<{s}> AS ?s) }} }} LIMIT 1",
            g = class.graph, c = class.name
        ))?;
        if hit.is_empty() {
            return Ok(None);
        }
        Ok(self.rows(class, &[s])?.into_iter().next())
    }
}
